const tabs=document.getElementById("tabs"),body=document.getElementById("menuBody"),toast=document.getElementById("toast");
let tt;
function say(t){toast.textContent=t;toast.classList.add("on");clearTimeout(tt);tt=setTimeout(()=>toast.classList.remove("on"),3200)}
const FOTOS={"Bowl de quinua y pollo":"data:image/jpeg;base64,","Ají de gallina light":"data:image/jpeg;base64,","Ensalada de salmón":"data:image/jpeg;base64,","Tacu tacu de lentejas":"data:image/jpeg;base64,","Lomo saltado light":"data:image/jpeg;base64,","Wrap integral de pavo":"data:image/jpeg;base64,","Mousse de maracuyá":"data:image/jpeg;base64,","Chia pudding de coco":"data:image/jpeg;base64,","Muffin de avena":"data:image/jpeg;base64,","Brownie de cacao y camote":"data:image/jpeg;base64,","Chicha morada":"data:image/jpeg;base64,","Limonada de hierbabuena":"data:image/jpeg;base64,","Naranjada sin azúcar":"data:image/jpeg;base64,","Té helado":"data:image/jpeg;base64,","Mousse de arándanos":"data:image/jpeg;base64,","Pescado a la plancha con puré de espárragos":"data:image/jpeg;base64,","Quinotto de hongos":"data:image/jpeg;base64,","Cheesecake de yogurt":"data:image/jpeg;base64,","Agua de piña":"data:image/jpeg;base64,","Buddha bowl vegano":"data:image/jpeg;base64,","Té helado de maracuyá":"data:image/jpeg;base64,","Limonada de fresa":"data:image/jpeg;base64,","Ensalada de lentejas":"data:image/jpeg;base64,","Pasta integral al pesto":"data:image/jpeg;base64,","Poke de atún":"data:image/jpeg;base64,","Tarta de manzana integral":"data:image/jpeg;base64,","Maracumango":"data:image/jpeg;base64,","Carrot cake con harina de avena":"data:image/jpeg;base64,","Hamburguesa de lentejas":"data:image/jpeg;base64,","Carambola":"data:image/jpeg;base64,","Pollo al horno":"data:image/jpeg;base64,","Agua de sandía":"data:image/jpeg;base64,","Wrap integral de garbanzo":"data:image/jpeg;base64,","Flan de plátano":"data:image/jpeg;base64,","Mazamorra de piña":"data:image/jpeg;base64,"};
function card(s){const [n,d,p,e]=s.split("|");return `<div class="item">${FOTOS[n]?`<img class="ph" src="${FOTOS[n]}" alt="${n}">`:`<div class="emo">${e}</div>`}<h4>${n}</h4><p>${d}</p><div class="price">S/ ${p}.00</div><button class="btn" data-n="${n}" data-p="${p}" data-d="${diaActual}">Agregar al carrito</button></div>`}
let diaActual="";
function show(dia){
  diaActual=dia;
  [...tabs.children].forEach(b=>b.setAttribute("aria-selected",b.textContent===dia));
  const m=M[dia];
  body.innerHTML=`<h3>Platos de fondo</h3><div class="grid">${m.p.map(card).join("")}</div><h3>Postres saludables</h3><div class="grid">${m.d.map(card).join("")}</div><h3>Bebidas</h3><div class="grid">${m.b.map(card).join("")}</div>`;
  rv(body);
}
dias.forEach(d=>{const b=document.createElement("button");b.className="tab";b.setAttribute("role","tab");b.textContent=d;b.onclick=()=>show(d);tabs.appendChild(b)});
const cart=[];
const MINIMO_GRATIS=38,TOPE_DELIVERY=6;
const ORIGEN={lat:-12.1276,lon:-77.0300}; // Av. Benavides con Av. Larco (punto aproximado: ajústalo a la puerta exacta de tu cocina)
const TRAMOS=[[2,5.4],[3,6.55],[4,7.65]]; // [hasta km, tarifa S/]
const money=n=>"S/ "+n.toFixed(2);
let tarifa=null,estado="",dirOk="",seq=0,tmr;
const MSG={"":"Ingresa tu dirección","calc":"Calculando…","noenc":"No encontramos esa dirección. Prueba con calle y número","lejos":"Fuera de zona de reparto","error":"Sin conexión con el mapa, intenta de nuevo"};
function tramo(km){for(const [m,f] of TRAMOS)if(km<=m)return f;return null}
function delivery(t){if(tarifa==null)return null;return t>MINIMO_GRATIS?Math.round(Math.max(0,tarifa-TOPE_DELIVERY)*100)/100:tarifa}
function hav(a,b,c,d){const r=x=>x*Math.PI/180,R=6371,dl=r(c-a),dn=r(d-b),h=Math.sin(dl/2)**2+Math.cos(r(a))*Math.cos(r(c))*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
let diag=[];
async function geo(q){
  let red=false;
  try{const r=await fetch("https://photon.komoot.io/api/?limit=5&lang=default&lat="+ORIGEN.lat+"&lon="+ORIGEN.lon+"&q="+encodeURIComponent(q));
    if(r.ok){red=true;const j=await r.json();const f=(j.features||[]).find(x=>x.properties&&x.properties.countrycode==="PE");if(f)return{p:{lat:f.geometry.coordinates[1],lon:f.geometry.coordinates[0]},red}}else diag.push("Photon "+r.status)}
  catch(x){diag.push("Photon: "+x.message);console.warn("Photon:",x)}
  try{const r=await fetch("https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=pe&accept-language=es&viewbox=-77.07,-12.09,-76.99,-12.17&q="+encodeURIComponent(q));
    if(r.ok){red=true;const j=await r.json();if(j.length)return{p:{lat:+j[0].lat,lon:+j[0].lon},red}}else diag.push("Nominatim "+r.status)}
  catch(x){diag.push("Nominatim: "+x.message);console.warn("Nominatim:",x)}
  return{p:null,red};
}
async function calcular(){
  const v=document.getElementById("dir").value.trim(),my=++seq;dirOk=v;
  if(v.length<6){tarifa=null;estado="";render();return}
  tarifa=null;estado="calc";diag=[];render();
  const limpio=v.replace(/[,;]?\s+(dpto|depto|departamento|piso|int|interior|oficina|of|mz|lote|lt)\b\.?\s*\w+.*$/i,"").trim();
  const consultas=[limpio+", Miraflores, Lima, Peru",limpio+", Lima, Peru"];
  let p=null,red=false;
  for(const q of consultas){const g=await geo(q);if(my!==seq)return;red=red||g.red;if(g.p){p=g.p;break}}
  if(!p){tarifa=null;estado=red?"noenc":"error";MSG.error="Sin conexión con el mapa ("+[...new Set(diag)].slice(0,3).join(" · ")+")";render();return}
  let km=hav(ORIGEN.lat,ORIGEN.lon,p.lat,p.lon)*1.25; // respaldo: línea recta + 25%
  try{const o=await fetch(`https://router.project-osrm.org/route/v1/driving/${ORIGEN.lon},${ORIGEN.lat};${p.lon},${p.lat}?overview=false`);if(o.ok){const oj=await o.json();if(oj.routes&&oj.routes[0])km=oj.routes[0].distance/1000}}catch(x){console.warn("OSRM:",x)}
  if(my!==seq)return;
  tarifa=tramo(km);estado=tarifa==null?"lejos":"ok";
  render();
}
const cartList=document.getElementById("cartList"),cnt=document.getElementById("cnt"),modal=document.getElementById("registro");
function render(){
  cnt.textContent=cart.reduce((a,i)=>a+i.q,0);
  const tot=cart.reduce((a,i)=>a+i.q*i.p,0);document.getElementById("barf").style.width=Math.min(100,tot/39*100)+"%";document.getElementById("free").textContent=tot>38?"🎉 ¡Delivery gratis! Asumimos hasta S/6 de la tarifa.":"Agrega S/ "+(39-tot)+" más y tienes delivery gratis (hasta S/6)";
  cartList.innerHTML=cart.length?cart.map((i,k)=>`<div class="line"><span>${i.n}<br><small style="color:var(--muted)">Para el ${i.d}</small></span><span><button type="button" data-k="${k}" data-d="-1">−</button> ${i.q} <button type="button" data-k="${k}" data-d="1">+</button></span><b>S/ ${i.q*i.p}.00</b></div>`).join("")+`<div class="line"><span>Productos</span><b>S/ ${tot}.00</b></div><div class="line"><span>Delivery${tarifa!=null&&tot>MINIMO_GRATIS?" <small style='color:var(--muted)'>(asumimos S/"+Math.min(TOPE_DELIVERY,tarifa)+")</small>":""}</span><b>${tarifa==null?"<small style='color:var(--muted)'>"+MSG[estado]+"</small>":(delivery(tot)>0?money(delivery(tot)):"Gratis")}</b></div><div class="line tot"><span>Total a pagar${tarifa==null?" <small style='color:var(--muted)'>(sin delivery)</small>":""}</span><b>${money(tot+(delivery(tot)||0))}</b></div>`:"<p>Tu carrito está vacío. Agrega platos desde el menú.</p>";
}
let user="";try{user=localStorage.getItem("brotaUser")||""}catch(x){}
function setModal(m,o){m.hidden=!o;document.body.style.overflow=o?"hidden":"";if(o){document.getElementById("msg").textContent="";document.getElementById("omsg").textContent="";render();document.getElementById("needreg").hidden=!!user}}
body.addEventListener("click",e=>{const b=e.target.closest("button[data-n]");if(!b)return;const n=b.dataset.n,p=+b.dataset.p,d=b.dataset.d,f=cart.find(i=>i.n===n&&i.d===d);if(f)f.q++;else cart.push({n,p,q:1,d});render();feedback(b);say("Agregado al carrito ("+d+"): "+n);ev("add_to_cart",{currency:"PEN",value:p,items:[{item_name:n,price:p,quantity:1}]})});
cartList.addEventListener("click",e=>{const b=e.target.closest("button[data-k]");if(!b)return;const k=+b.dataset.k;cart[k].q+=+b.dataset.d;if(cart[k].q<=0)cart.splice(k,1);render()});
const cartModal=document.getElementById("carrito");
const dirEl=document.getElementById("dir");
dirEl.addEventListener("input",()=>{tarifa=null;estado="";clearTimeout(tmr);tmr=setTimeout(calcular,900);render()});
dirEl.addEventListener("change",()=>{clearTimeout(tmr);calcular()});
document.getElementById("openCart").onclick=()=>setModal(cartModal,true);
document.getElementById("openReg").onclick=()=>setModal(modal,true);
document.getElementById("goReg").onclick=e=>{e.preventDefault();setModal(cartModal,false);setModal(modal,true)};
document.getElementById("close").onclick=()=>setModal(modal,false);
document.getElementById("closeCart").onclick=()=>setModal(cartModal,false);
[modal,cartModal].forEach(m=>m.addEventListener("click",e=>{if(e.target===m)setModal(m,false)}));
document.getElementById("ord").addEventListener("submit",e=>{
  e.preventDefault();
  const m=document.getElementById("omsg");
  if(!cart.length){m.textContent="Agrega al menos un producto al carrito antes de comprar.";return}
  if(!user){m.textContent="Para completar tu compra, primero regístrate.";return}
  if(dirOk!==dirEl.value.trim()||estado==="calc"){m.textContent="Estamos calculando el delivery de tu dirección, intenta en un momento.";calcular();return}
  if(tarifa==null){m.textContent=estado==="lejos"?"Lo sentimos, tu dirección está fuera de nuestra zona de reparto.":estado==="noenc"?"No encontramos tu dirección. Revísala e incluye calle y número.":"Ingresa una dirección válida para calcular el delivery.";return}
  const h=document.getElementById("hora").value,sub=cart.reduce((a,i)=>a+i.q*i.p,0),dl=delivery(sub);
  ev("purchase",{transaction_id:"T"+Date.now(),currency:"PEN",value:cart.reduce((a,i)=>a+i.q*i.p,0),items:cart.map(i=>({item_name:i.n,price:i.p,quantity:i.q}))});
  say("¡Gracias por tu preferencia"+(user?", "+user:"")+"!");confetti();
  cart.length=0;tarifa=null;estado="";dirOk="";e.target.reset();render();
  m.textContent="¡Gracias por tu preferencia! Recibimos tu pedido. Total a pagar: "+money(sub+dl)+" (delivery: "+(dl?money(dl):"gratis")+"). Hora de entrega solicitada: "+h+".";
});
// ---- Chat con el equipo de ventas (atención personalizada, sin chatbot) ----
const TEMAS=[
["Estado de mi pedido","Quisiera saber el estado de mi pedido. "],
["Cambiar mi dirección","Quiero cambiar la dirección de entrega de mi pedido. Nueva dirección en Miraflores: "],
["Problema con mi pedido","Tuve un problema con mi pedido: "],
["Alergias e ingredientes","Tengo una consulta sobre alergias o ingredientes de: "],
["Calificar mi experiencia","Quiero calificar mi pedido del 1 al 5. Mi calificación es: "],
["Cancelar un pedido","Quiero cancelar mi pedido. "]
];
const chat=document.getElementById("chat"),cm=document.getElementById("cmsgs"),chBtn=document.getElementById("chatBtn"),cin=document.getElementById("cin"),cname=document.getElementById("cname"),chips=document.getElementById("chips");
function bub(t,c){const d=document.createElement("div");d.className="b "+c;d.textContent=t;cm.appendChild(d);cm.scrollTop=cm.scrollHeight}
chips.innerHTML=TEMAS.map((x,i)=>`<button type="button" data-i="${i}">${x[0]}</button>`).join("");
chips.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;cin.value=TEMAS[+b.dataset.i][1];cin.focus()});
function setChat(o){
  chat.hidden=!o;chBtn.hidden=o;if(o)ev("chat_open");
  if(!o)return;
  if(user&&!cname.value)cname.value=user;
  cin.focus();
}
chBtn.onclick=()=>setChat(true);
document.getElementById("goChat").onclick=()=>setChat(true);
document.getElementById("chatX").onclick=()=>setChat(false);
document.getElementById("cform").addEventListener("submit",e=>{
  e.preventDefault();
  const v=cin.value.trim(),n=cname.value.trim();
  if(!v||!n)return;
  bub(v,"me");
  const st=document.createElement("small");st.textContent="Enviado ✓";st.style.cssText="align-self:flex-end;font-size:.75rem;color:var(--muted)";cm.appendChild(st);cm.scrollTop=cm.scrollHeight;
  cin.value="";
});
// ---- Medición (Google Analytics): no hace nada si GA no está instalado ----
function ev(n,p){try{if(window.gtag)gtag("event",n,p||{})}catch(x){}}
// ---- Efectos visuales e interactivos ----
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("in");io.unobserve(e.target)}}),{threshold:.12});
function rv(root){root.querySelectorAll(".pill,.item,#nosotros h2,#menu h2,#encuentranos h2,#escribenos h2,#pagos h2").forEach(el=>{el.classList.add("rv");io.observe(el)})}
rv(document);
document.getElementById("collage").innerHTML=["Bowl de quinua y pollo","Ensalada de salmón","Mousse de maracuyá"].map(n=>`<img src="${FOTOS[n]}" alt="${n}">`).join("");
function feedback(b){b.textContent="✓ Agregado";b.classList.add("ok");setTimeout(()=>{b.textContent="Agregar al carrito";b.classList.remove("ok")},1100);const c=document.getElementById("openCart");c.classList.remove("bump");void c.offsetWidth;c.classList.add("bump")}
function confetti(){for(let i=0;i<24;i++){const s=document.createElement("span");s.className="cf";s.textContent=["🥗","🍓","🥑","🍋","🎉"][i%5];s.style.left=Math.random()*100+"vw";s.style.animationDelay=Math.random()*.6+"s";document.body.appendChild(s);setTimeout(()=>s.remove(),3200)}}
const lb=document.getElementById("lb"),lbi=document.getElementById("lbi"),lbp=document.getElementById("lbp");
body.addEventListener("click",e=>{const im=e.target.closest(".ph");if(!im)return;const it=im.closest(".item");lbi.src=im.src;lbp.textContent=it.querySelector("h4").textContent+" — "+it.querySelector("p").textContent;lb.hidden=false});
lb.onclick=()=>{lb.hidden=true};
document.getElementById("theme").onclick=()=>{const d=document.documentElement;const dark=d.dataset.theme?d.dataset.theme==="dark":matchMedia("(prefers-color-scheme:dark)").matches;d.dataset.theme=dark?"light":"dark"};
// abre el día actual (domingo -> lunes)
const hoy=["Domingo","Lunes","Martes","Miércoles","Jueves","Viernes","Sábado"][new Date().getDay()];
show(dias.includes(hoy)?hoy:"Lunes");
document.getElementById("reg").addEventListener("submit",e=>{
  e.preventDefault();
  const n=document.getElementById("nombre").value.trim();
  const ed=document.getElementById("edad").value.trim();
  user=n;try{localStorage.setItem("brotaUser",n);localStorage.setItem("brotaEdad",ed)}catch(x){}ev("sign_up",{method:"formulario"});
  document.getElementById("msg").textContent="¡Bienvenido/a, "+n+"! Ya estás registrado/a.";
  say("¡Registro exitoso, gracias por tu preferencia!");e.target.reset();
  if(cart.length)setTimeout(()=>{setModal(modal,false);setModal(cartModal,true)},900);
});
